import test,{before,after} from 'node:test';import assert from 'node:assert/strict';import {randomUUID as uid}from'node:crypto';import{readFile,writeFile}from'node:fs/promises';import{resolve}from'node:path';
import{isolatedRefund,write}from'../support/h4-refund-isolated.ts';import{refundFixture}from'../support/h4-refund-fixtures.ts';
let h:Awaited<ReturnType<typeof isolatedRefund>>;before(async()=>{h=await isolatedRefund('crm_f23',56960,false,false);if(!process.env.H4016_F23_REPRO)await h.migration.unsafe(await readFile('supabase/migrations/20261006065228_h4_refund_uncertain_partial_progress.sql','utf8'));});after(async()=>{await h?.close();});
const setup=async()=>{const f=await refundFixture(h);await f.run(await f.determine());await(await f.approval(await f.authorization())).execute();const inc=await f.incident(),attempt={id:uid(),sourceRef:'SYNTHETIC same attempted transfer outcome uncertain',portion:await f.portion('80.00')};await f.run(await f.command('uncertain',{attempt,incidentId:inc.incidentId}));return{f,inc,attempt};};
test('F23 C01/C02 original ordinary route denied, linked partial progress must succeed',async()=>{const{f,attempt}=await setup(),ordinary=await f.movement('20.00'),q=await f.command('resolve',{attemptId:attempt.id,resolution:'occurred',movement:ordinary.movement}),before=await f.view(),fundsBefore=await f.a.see();let ordinaryError='',error='';await assert.rejects(f.run(ordinary),e=>{ordinaryError=String(e);return /PORTIONS_REQUIRED/.test(ordinaryError);});try{await f.run(q);}catch(e){error=String(e);}const after=await f.view(),fundsAfter=await f.a.see();if(process.env.H4014_CAPTURE_DIR)await writeFile(resolve(process.env.H4014_CAPTURE_DIR,'F23-original-state.json'),JSON.stringify({ordinary,q,before,fundsBefore,ordinaryError,error,after,fundsAfter},null,2)+'\n');assert.equal(error,'');assert.equal(after.executed,'20.00');assert.equal(after.pendingRight,'180.00');assert.equal(after.pendingAuthorized,'180.00');assert.equal(after.uncertain,'60.00');assert.equal(fundsAfter.summary.refundReserved,'60.00');assert.equal(after.attempts[0].resolved,false);assert.deepEqual(after.attempts[0].portion,before.attempts[0].portion);});
test('F23 C02 ordinary record cannot bypass uncertain reserve by supplying attemptId',async()=>{const{f,attempt}=await setup(),q=await f.movement('20.00','0.00',{attemptId:attempt.id}),before=await f.view();let error='';try{await f.run(q);}catch(e){error=String(e);}const after=await f.view();if(process.env.H4014_CAPTURE_DIR)await writeFile(resolve(process.env.H4014_CAPTURE_DIR,'F24-original-state.json'),JSON.stringify({q,before,error,after,funds:await f.a.see()},null,2)+'\n');assert.notEqual(error,'');assert.deepEqual(after,before);});
const partial=async(f:Awaited<ReturnType<typeof refundFixture>>,attempt:{id:string},amount='20.00',start='0.00')=>{const move=await f.movement(amount,start);return f.command('resolve',{attemptId:attempt.id,resolution:'occurred',movement:move.movement});};
for(const result of ['not_occurred','occurred']as const)test('F23 C03/C04 partial20 then rest60 '+result,async()=>{const{f,attempt}=await setup(),original=await f.view();await f.run(await partial(f,attempt));const q=result==='occurred'?await partial(f,attempt,'60.00','20.00'):await f.command('resolve',{attemptId:attempt.id,resolution:result});await f.run(q);const v=await f.view();assert.equal(v.executed,result==='occurred'?'80.00':'20.00');assert.equal(v.pendingRight,result==='occurred'?'120.00':'180.00');assert.equal(v.pendingAuthorized,v.pendingRight);assert.equal(v.uncertain,'0.00');assert.equal(v.attempts[0].resolved,true);assert.deepEqual(v.attempts[0].portion,original.attempts[0].portion);assert.equal(v.movements.length,result==='occurred'?2:1);assert.equal(v.movements[0].material.sourceAttemptId,attempt.id);assert.equal(v.attempts[0].progress.length,2);assert.equal((await f.a.see()).summary.refundReserved,'0.00');});
test('F23 C08 interior disjoint partials preserve both remaining ranges',async()=>{const{f,attempt}=await setup();await f.run(await partial(f,attempt,'20.00','20.00'));let v=await f.view();assert.equal(v.uncertain,'60.00');assert.deepEqual(v.attempts[0].remainingPortions.map((p:any)=>[p.start,p.amount]),[['0.00','20.00'],['40.00','40.00']]);await f.run(await partial(f,attempt,'20.00','0.00'));await f.run(await partial(f,attempt,'40.00','40.00'));v=await f.view();assert.equal(v.executed,'80.00');assert.equal(v.uncertain,'0.00');assert.equal((await f.a.see()).summary.representedReturned,'80.00');});
for(const mode of ['outside','amount','payment','reconciliation','recipient','method','attempt','candidate','crossed','duplicate','approval','missingEvidence'])test('F23 C05/C06 individual guard '+mode,async()=>{const{f,attempt}=await setup();let q=await partial(f,attempt);if(mode==='duplicate'){await f.run(q);q=await partial(f,attempt);}else if(mode==='approval'){await f.run(await f.command('revoke'));q=await partial(f,attempt);}else if(mode==='candidate'){q=await f.attest(q,'candidate');}else if(mode==='crossed'){const other=await setup();q.evidenceId=(await partial(other.f,other.attempt)).evidenceId;}else if(mode==='missingEvidence'){q.evidenceId=uid();}else{const m:any=q.movement!;if(mode==='outside')m.portions[0]!.start='100.00';if(mode==='amount')m.amount='21.00';if(mode==='payment')m.portions[0]!.paymentId=uid();if(mode==='reconciliation')m.portions[0]!.reconciliationId=uid();if(mode==='recipient')m.recipientId=uid();if(mode==='method')m.method='cash';if(mode==='attempt')q.attemptId=uid();q=await f.attest(q);}const before=await f.view(),fund=await f.a.see();await assert.rejects(f.run(q));assert.deepEqual(await f.view(),before);assert.deepEqual(await f.a.see(),fund);});
test('F23 C06 Incident resolved never releases remaining60 or permits dangerous retry',async()=>{const{f,attempt,inc}=await setup();await f.run(await partial(f,attempt));await h.incidents.apply(await h.auth(),write,await inc.resolve());await assert.rejects(f.run(await f.movement('60.00','20.00')));await assert.rejects(h.allocations.apply(await h.auth(),write,await f.a.assign('80.00')));assert.equal((await f.view()).uncertain,'60.00');assert.equal((await f.view()).executed,'20.00');});
test('F23 C07 replay and same fact after technical fund revision: one linked movement',async()=>{const{f,attempt}=await setup(),q=await partial(f,attempt);await f.run(q);let v=await f.view();assert.equal((await f.run(q)).replayed,true);assert.equal((await f.view()).revision,v.revision);const fresh=await f.portion('20.00');const again=await f.attest({...q,operationId:uid(),expectedRevision:v.revision,movement:{...q.movement!,portions:[fresh]}});assert.equal((await f.run(again)).replayed,true);v=await f.view();assert.equal(v.executed,'20.00');assert.equal(v.uncertain,'60.00');assert.equal(v.movements.length,1);const changed=await f.attest({...again,movement:{...again.movement!,reference:'SYNTHETIC different material'}});await assert.rejects(f.run(changed),/CONFLICT:E2/);const wrongAttempt=await f.attest({...again,operationId:uid(),attemptId:uid()});await assert.rejects(f.run(wrongAttempt),/CONFLICT:E2/);assert.equal((await f.view()).movements.length,1);});
const delay=(ms:number)=>new Promise(r=>setTimeout(r,ms));
async function overlap(f:Awaited<ReturnType<typeof refundFixture>>,jobs:(()=>Promise<any>)[],order:number[],payment=false){const block=h.connect('crm_h0_migration');await block.unsafe('begin');if(payment)await block`select pg_advisory_xact_lock(hashtextextended(${'payment-root:'+f.a.paymentId},0))`;else await block`select pg_advisory_xact_lock(hashtextextended(${f.c.b.opportunityId},31))`;const pending:Promise<any>[]=[];try{for(let i=0;i<order.length;i++){pending.push(jobs[order[i]!]!().then(value=>({ok:true,value}),error=>({ok:false,error:String(error)})));let count=0;for(let n=0;n<150;n++){count=Number((await h.admin`select count(*)::int n from pg_stat_activity where usename in('crm_h0_runtime','crm_h0_ha_tx')and wait_event_type='Lock'`)[0]!.n);if(count>=i+1)break;await delay(10);}console.log('F23 PostgreSQL independent sessions Lock overlap',order,'queued',i+1,'observed',count);assert.ok(count>=i+1);}await block.unsafe('rollback');return await Promise.all(pending);}finally{await block.unsafe('rollback');await block.end();}}
for(const order of [[0,1],[1,0]])for(const mode of ['overlap','disjoint','sameFact','rest','allocation'])test('F23 C09 actual PostgreSQL race '+mode+' '+order,async()=>{const{f,attempt}=await setup();if(mode==='allocation')await f.run(await partial(f,attempt));const q=await partial(f,attempt,'20.00',mode==='allocation'?'20.00':'0.00');let other=await partial(f,attempt,'20.00',mode==='disjoint'?'20.00':'0.00');let second=()=>f.run(other);if(mode==='sameFact'){other=await f.attest({...q,operationId:uid()});second=()=>f.run(other);}if(mode==='rest'){other=await f.command('resolve',{attemptId:attempt.id,resolution:'not_occurred'});second=()=>f.run(other);}if(mode==='allocation'){const alloc=await f.a.assign('20.00','20.00');second=async()=>h.allocations.apply(await h.auth(),write,alloc);}const result=await overlap(f,[()=>f.run(q),second],order,mode==='allocation');assert.equal(result.filter(x=>x.ok).length,mode==='sameFact'?2:1);let v=await f.view();assert.equal(v.executed,mode==='rest'&&order[0]===1?'0.00':mode==='allocation'?'40.00':'20.00');if(mode==='rest'&&order[0]===1)assert.equal(v.uncertain,'0.00');else assert.equal(v.uncertain,mode==='allocation'?'40.00':'60.00');if(mode==='disjoint'){const rejectedIndex=result.findIndex(x=>!x.ok),retry=await partial(f,attempt,'20.00',order[rejectedIndex]===0?'0.00':'20.00');await f.run(retry);v=await f.view();assert.equal(v.executed,'40.00');assert.equal(v.uncertain,'40.00');}assert.equal(v.movements.length,['disjoint','allocation'].includes(mode)?2:v.executed==='0.00'?0:1);});
import{refundTables}from'../support/h4-refund-isolated.ts';import{H4015RefundAdapter}from'../../src/infrastructure/postgres/h4-refund-adapter.ts';
const snapshot=async()=>Object.fromEntries(await Promise.all([...refundTables,'b05_fund_revisions','b05_coverage_evaluations'].map(async n=>[n,(await h.observer.unsafe(`select to_jsonb(x)::text value from crm_private.${n} x order by to_jsonb(x)::text`)).map(x=>x.value)])));
for(const table of ['b05_refund_movements','b05_refund_revisions','b05_refund_operations','b05_fund_revisions'])test('F23 C10 atomic partial fault '+table,async()=>{const{f,attempt}=await setup(),q=await partial(f,attempt),before=await snapshot();await h.admin.unsafe("create function crm_private.f23_fault()returns trigger language plpgsql as $$begin raise exception 'SYNTHETIC_F23_FAULT';end$$");await h.admin.unsafe(`create trigger f23_fault before insert on crm_private.${table} for each row execute function crm_private.f23_fault()`);try{await assert.rejects(f.run(q));assert.deepEqual(await snapshot(),before);}finally{await h.admin.unsafe(`drop trigger f23_fault on crm_private.${table}`);await h.admin.unsafe('drop function crm_private.f23_fault()');}await f.run(q);assert.equal((await f.view()).executed,'20.00');assert.equal((await f.view()).uncertain,'60.00');});
test('F23 C10 partial deferred COMMIT fault exact rollback retry',async()=>{const{f,attempt}=await setup(),q=await partial(f,attempt),before=await snapshot();await h.admin.unsafe("create function crm_private.f23_commit()returns trigger language plpgsql as $$begin raise exception 'SYNTHETIC_F23_COMMIT';end$$");await h.admin.unsafe('create constraint trigger f23_commit after insert on crm_private.b05_refund_operations deferrable initially deferred for each row execute function crm_private.f23_commit()');try{await assert.rejects(f.run(q));assert.deepEqual(await snapshot(),before);}finally{await h.admin.unsafe('drop trigger f23_commit on crm_private.b05_refund_operations');await h.admin.unsafe('drop function crm_private.f23_commit()');}await f.run(q);assert.equal((await f.view()).uncertain,'60.00');});
test('F23 C10 response lost after real COMMIT durable linked partial recovery',async()=>{const{f,attempt}=await setup(),q=await partial(f,attempt),lost={begin:async(options:any,work:any)=>{await h.runtime.begin(options,work);throw new Error('SYNTHETIC_LOST_AFTER_REAL_COMMIT');}}as unknown as typeof h.runtime;await assert.rejects(new H4015RefundAdapter(lost,h.f1,h.f2).apply(await h.auth(),write,q));assert.equal((await f.view()).executed,'20.00');const before=await snapshot();assert.equal((await f.run(q)).replayed,true);assert.deepEqual(await snapshot(),before);});
test('F23 C11 private helper no runtime/anon/authenticated execution, safe path',async()=>{for(const role of ['crm_h0_runtime','anon','authenticated']){const db=h.connect(role);try{await assert.rejects(db.unsafe("select crm_private.refund_attempt_remaining('{}'::jsonb)"));for(const t of refundTables)await assert.rejects(db.unsafe(`select * from crm_private.${t}`));}finally{await db.end();}}const p=(await h.observer`select proconfig,pg_get_userbyid(proowner)owner from pg_proc where oid='crm_private.refund_attempt_remaining(jsonb)'::regprocedure`)[0]!;assert.equal(p.owner,'crm_h0_f2_owner');assert.deepEqual(p.proconfig,['search_path=pg_catalog, pg_temp']);});
for(const mode of ['actor','session'])test('F23 C11 partial replay revoked '+mode,async()=>{const u=await isolatedRefund('crm_f23_rev_'+mode,mode==='actor'?56967:56968,false,true);try{const f=await refundFixture(u);await f.run(await f.determine());await(await f.approval(await f.authorization())).execute();const inc=await f.incident(),attempt={id:uid(),sourceRef:'SYNTHETIC uncertain attempt',portion:await f.portion('80.00')};await f.run(await f.command('uncertain',{attempt,incidentId:inc.incidentId}));const q=await partial(f,attempt);await f.run(q);const auth=await u.auth();if(mode==='actor')await u.admin`update crm_private.crm_actors set enabled=false where actor_id=${u.actorId}::uuid`;else await u.admin`update crm_private.crm_sessions set revoked_at=clock_timestamp()where session_id=${u.sessionId}::uuid`;await assert.rejects(u.refunds.apply(auth,write,q));const v=(await u.observer`select after_data from crm_private.b05_refund_revisions where refund_id=${f.id}::uuid order by revision desc limit 1`)[0]!.after_data;assert.equal(v.executed,'20.00');assert.equal(v.uncertain,'60.00');}finally{await u.close();}});
test('F23 C11 partial minimal projection and unknown or crossed scope denied',async()=>{const{f,attempt}=await setup();await f.run(await partial(f,attempt));const r=await h.refunds.read(await h.auth(),(await import('../support/h4-refund-isolated.ts')).read,f.bid,f.id,'summary');assert.deepEqual(Object.keys(r).sort(),['id','revision','right','authorized','executed','pendingRight','pendingAuthorized','uncertain','status'].sort());const other=await setup();assert.equal(await h.refunds.read(await h.auth(),(await import('../support/h4-refund-isolated.ts')).read,other.f.bid,f.id),null);const q=await partial(f,attempt,'20.00','20.00');await assert.rejects(f.run({...q,bookingId:other.f.bid}));assert.equal((await f.view()).uncertain,'60.00');});
